django_user_model = <class 'apps.accounts.models.Account'>, name = '白细胞计数' code = 'LAB_WBC', unit = '10^9/L', expected = '3.5–9.5'
@pytest.mark.parametrize('name,code,unit,expected', [ ('白细胞计数', 'LAB_WBC', '10^9/L', '3.5–9.5'), ('血红蛋白', 'LAB_HGB', 'g/L', '115–150'), ('睾酮', 'LAB_CATALOG_045', 'nmol/L', '0.35–2.6'), ('泌乳素', 'LAB_CATALOG_046', 'mIu/L', '70.81–566.46'), ]) def test_non_phase_references_appear_once_under_indicator_not_in_results( django_user_model, name, code, unit, expected): client, patient = _patient(django_user_model, 'catalog-reference-position-' + code) patient.sex, patient.birth_date = 'F', date(2000, 1, 1) patient.save() for day in (20, 21): observation = indicator(patient, name=name, code=code, unit=unit, day=date(2026, 9, day)) # A report's phase field does not make an ordinary indicator phase-dependent. observation.physiological_phase = '卵泡期' observation.save(update_fields=['physiological_phase']) html = client.get('/labs/compare/', {'patient': patient.pk}).content.decode() heading = re.search(r'<th scope="row">.*?</th>', html, re.S).group() results = re.findall(r'<article>.*?</article>', html, re.S) > assert f'标准参考范围：{expected} {unit}' in heading E assert '标准参考范围：3.5–9.5 10^9/L' in '<th scope="row">白细胞计数\n \n </th>'
